    address: factory,
    fromBlock: 10,
    toBlock: 20,
  } satisfies LogFilter;

  await syncStore.insertIntervals({
    intervals: [{ filter, interval: [10, 20] }],
    factoryIntervals: [{ factory, interval: [10, 20] }],
